SELECT id, account_type, status, RANK() OVER w_part balance_rank, SUM(balance) OVER (PARTITION BY status) status_sum_balance, SUM(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_balance, NTILE(3) OVER w_grp balance_bucket, FIRST_VALUE(status) IGNORE NULLS OVER w_grp_2 first_known_status FROM accounts WHERE balance BETWEEN 75000 AND 76000 WINDOW w_part AS (ORDER BY balance NULLS FIRST), w_grp AS (ORDER BY balance DESC, id), w_grp_2 AS (ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
